def get_alarms_from_all_pages(instance, alarm_type, timeout, **kwargs):
    """Fetches all alarms (active or historical) from all pages."""
    if alarm_type not in ["active", "historical"]:
        raise ValueError("Invalid alarm_type. Choose 'active' or 'historical'.")

    method = getattr(instance, f"get_{alarm_type}_alarms", None)

    response = method(
        page_number=1,
        items_per_page=100,
        timeout=timeout,
        **kwargs
    )

    alarms = response["alarms"]
    total = response["total"]

    page_number = 2
    while len(alarms) != total:
        response = method(
            page_number=page_number,
            items_per_page=100,
            timeout=timeout,
            **kwargs
        )

        alarms.extend(response["alarms"])
        page_number += 1

    return {"alarms": alarms, "total": total}
